CREATE PROCEDURE p_sum_qty
AS
BEGIN
  DECLARE @id int, @q int, @tot int;
  SET @tot = 0;
  DECLARE c1 CURSOR LOCAL FAST_FORWARD FOR
    SELECT id, qty FROM item ORDER BY id DESC;
  OPEN c1;
  FETCH NEXT FROM c1 INTO @id, @q;
  WHILE (@@FETCH_STATUS = 0)
  BEGIN
    SET @tot = @tot + @q;
    FETCH NEXT FROM c1 INTO @id, @q;
  END;
  CLOSE c1;
  DEALLOCATE c1;
  SELECT @tot AS total;
END;

