CREATE PROCEDURE p_region_report @region varchar(5)
AS
BEGIN
  IF @region IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cust WHERE region = @region)
  BEGIN
    RAISERROR('Unknown region %s', 16, 1, @region);
    RETURN 1;
  END;
  IF @region = NULL
    SELECT c.id, c.name, SUM(o.amt) AS total
    FROM cust c LEFT OUTER JOIN ord o ON c.id = o.cust_id
    WHERE c.region IS NULL
    GROUP BY c.id, c.name
