CREATE PROCEDURE p_purge @before int
AS
BEGIN
  DECLARE @rows int, @total int;
  SET @total = 0;
  DELETE TOP (2) FROM audit_log WHERE ts < @before;
  SET @rows = @@ROWCOUNT;
  WHILE @rows >= 0
  BEGIN
    SET @total = @total + @rows;
    DELETE TOP (2) FROM audit_log WHERE ts < @before;
    SET @rows = @@ROWCOUNT;
  END;
  PRINT 'Purged ' + CAST(@total AS varchar(12)) + ' rows';
  SELECT COUNT(*) AS remaining FROM audit_log;
END;

